#define MAX_COLS 32
static int csvrow(char *line,char **out,int cap){int n=0;char *r=line,*w=line;while(*r&&n<cap){if(*r=='\n'||*r=='\r')break;out[n++]=w;if(*r=='"'){r++;while(*r){if(*r=='"'&&r[1]=='"'){*w++='"';r+=2;continue;}if(*r=='"'){r++;break;}*w++=*r++;}while(*r&&*r!=','){if(*r=='\n'||*r=='\r')break;r++;}if(*r==','){*w++='\0';r++;}else{*w++='\0';break;}}else{while(*r&&*r!=','&&*r!='\n'&&*r!='\r')*w++=*r++;if(*r==','){*w++='\0';r++;}else{*w++='\0';break;}}}return n;}
static void xml(FILE *f,const char *s){for(;*s;s++){switch(*s){case '&':fputs("&amp;",f);break;case '<':fputs("&lt;",f);break;case '>':fputs("&gt;",f);break;case '"':fputs("&quot;",f);break;case '\'':fputs("&apos;",f);break;default:fputc(*s,f);}}}
static void colname(int n,char *b){char t[16];int k=0;while(n>0){int r=(n-1)%26;t[k++]=(char)('A'+r);n=(n-1)/26;}int j=0;while(k)b[j++]=t[--k];b[j]=0;}
static void csv_to_sheet(const char *csv,const char *sheet){FILE *in=fopen(csv,"r");if(!in){perror(csv);exit(2);}FILE *out=fopen(sheet,"w");if(!out){perror(sheet);exit(2);}fputs("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData>",out);char *line=NULL;size_t cap=0;int row=0;while(getline(&line,&cap,in)>=0){char *v[MAX_COLS];int n=csvrow(line,v,MAX_COLS);row++;fprintf(out,"<row r=\"%d\">",row);for(int c=0;c<n;c++){char cn[16],ref[32];colname(c+1,cn);snprintf(ref,sizeof(ref),"%s%d",cn,row);char *end=NULL;errno=0;double x=strtod(v[c],&end);int numeric=(v[c][0]&&end&&*end=='\0'&&end!=v[c]&&!errno);if(numeric)fprintf(out,"<c r=\"%s\"><v>%s</v></c>",ref,v[c]);else{fprintf(out,"<c r=\"%s\" t=\"inlineStr\"><is><t xml:space=\"preserve\">",ref);xml(out,v[c]);fputs("</t></is></c>",out);}}fputs("</row>",out);}fputs("</sheetData></worksheet>",out);free(line);fclose(in);fclose(out);}
int main(int argc,char **argv){const char *dir=argc>1?argv[1]:"results";const char *outpath=argc>2?argv[2]:"results/SecR2R_C_Entropy_Results.xlsx";char cmd[2048],p[1024];snprintf(p,sizeof(p),"%s/xlsx_tmp",dir);mkdir(p,0775);snprintf(p,sizeof(p),"%s/xlsx_tmp/_rels",dir);mkdir(p,0775);snprintf(p,sizeof(p),"%s/xlsx_tmp/xl",dir);mkdir(p,0775);snprintf(p,sizeof(p),"%s/xlsx_tmp/xl/_rels",dir);mkdir(p,0775);snprintf(p,sizeof(p),"%s/xlsx_tmp/xl/worksheets",dir);mkdir(p,0775);
 char *names[]={"Entropy Summary","Weekly Metrics","Per-Cell Entropy","Device Enrollment"};char *csvs[]={"entropy_summary.csv","entropy_summary_weekly.csv","entropy_summary_per_cell_entropy.csv","entropy_summary_device_enrollment.csv"};
 for(int i=0;i<4;i++){char cpath[1024],spath[1024];snprintf(cpath,sizeof(cpath),"%s/%s",dir,csvs[i]);snprintf(spath,sizeof(spath),"%s/xlsx_tmp/xl/worksheets/sheet%d.xml",dir,i+1);csv_to_sheet(cpath,spath);}
 snprintf(p,sizeof(p),"%s/xlsx_tmp/[Content_Types].xml",dir);FILE*f=fopen(p,"w");if(!f)exit(2);fputs("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/>",f);for(int i=1;i<=4;i++)fprintf(f,"<Override PartName=\"/xl/worksheets/sheet%d.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>",i);fputs("</Types>",f);fclose(f);
 snprintf(p,sizeof(p),"%s/xlsx_tmp/_rels/.rels",dir);f=fopen(p,"w");if(!f)exit(2);fputs("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>",f);fclose(f);
 snprintf(p,sizeof(p),"%s/xlsx_tmp/xl/workbook.xml",dir);f=fopen(p,"w");if(!f)exit(2);fputs("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets>",f);for(int i=0;i<4;i++)fprintf(f,"<sheet name=\"%s\" sheetId=\"%d\" r:id=\"rId%d\"/>",names[i],i+1,i+1);fputs("</sheets></workbook>",f);fclose(f);
 snprintf(p,sizeof(p),"%s/xlsx_tmp/xl/_rels/workbook.xml.rels",dir);f=fopen(p,"w");if(!f)exit(2);fputs("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">",f);for(int i=1;i<=4;i++)fprintf(f,"<Relationship Id=\"rId%d\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet%d.xml\"/>",i,i);fputs("</Relationships>",f);fclose(f);
 /* zip from the workbook root so OOXML paths are correct */
 char cwd[PATH_MAX]; if(!getcwd(cwd,sizeof(cwd))) {perror("getcwd");return 2;} char absout[PATH_MAX]; if(outpath[0]=='/') snprintf(absout,sizeof(absout),"%s",outpath); else snprintf(absout,sizeof(absout),"%s/%s",cwd,outpath); snprintf(cmd,sizeof(cmd),"cd '%s/xlsx_tmp' && zip -q -r '%s' '[Content_Types].xml' _rels xl",dir,absout);int rc=system(cmd);if(rc!=0){fprintf(stderr,"ERROR: zip command failed; install a zip utility and retry.\n");return 3;}printf("Excel workbook written: %s\n",outpath);return 0;}
